JS
= Sql.Database("192.168.3.212\JSMS", "DISTRIBUTOR_DATAMART", [Query="SELECT RTRIM(almacen) AS ALMACEN, #(lf)    ccod_prod,#(lf)    COUNT(CASE WHEN DATEDIFF(day, fcompra, GETDATE()) BETWEEN 0 AND 15 THEN 1 END) AS [0-15 dias],#(lf)    COUNT(CASE WHEN DATEDIFF(day, fcompra, GETDATE()) > 15 AND DATEDIFF(day, fcompra, GETDATE()) <= 30 THEN 1 END) AS [15-30 dias],#(lf)    COUNT(CASE WHEN DATEDIFF(day, fcompra, GETDATE()) > 30 AND DATEDIFF(day, fcompra, GETDATE()) <= 70 THEN 1 END) AS [30-70 dias],#(lf)    COUNT(CASE WHEN DATEDIFF(day, fcompra, GETDATE()) > 70 AND DATEDIFF(day, fcompra, GETDATE()) <= 90 THEN 1 END) AS [70-90 dias],#(lf)    COUNT(CASE WHEN DATEDIFF(day, fcompra, GETDATE()) > 90 THEN 1 END) AS [Mas de 90 dias],#(lf)    COUNT(*) AS Stock,#(lf)#(tab)AVG(ncosto) as stock_costo_promedio#(lf)FROM [192.168.3.101,1800\MSSQL_NEW].[Distribuidora].[dbo].[WOLAP_CONSULTA_SERIES]#(lf)WHERE ALMACEN IN (#(lf)    'AREQUIPA                            ', 'Ayacucho                            ', #(lf)    'Cusco                               ', 'E-COMMERCE                          ', #(lf)    'Huancayo                            ', 'Huánuco                             ', #(lf)    'Ica                                 ', 'La Merced                           ', #(lf)    'Lima Sur                            ', 'Pucallpa                            ', #(lf)    'Puno                                '#(lf)) #(lf)AND LINEA IN ('ACCESORIOS                    ', 'EQUIPOS                       ', 'UTILES                        ')#(lf)GROUP BY RTRIM(almacen), ccod_prod#(lf)"])


AMAZONIA
= Sql.Database("192.168.3.212\JSMS", "DISTRIBUTOR_DATAMART", [Query="SELECT nombrepv AS ALMACEN, #(lf)    codigo as ccod_prod,#(lf)    COUNT(CASE WHEN DATEDIFF(day, fechafactura, GETDATE()) BETWEEN 0 AND 15 THEN 1 END) AS [0-15 dias],#(lf)    COUNT(CASE WHEN DATEDIFF(day, fechafactura, GETDATE()) > 15 AND DATEDIFF(day, fechafactura, GETDATE()) <= 30 THEN 1 END) AS [15-30 dias],#(lf)    COUNT(CASE WHEN DATEDIFF(day, fechafactura, GETDATE()) > 30 AND DATEDIFF(day, fechafactura, GETDATE()) <= 70 THEN 1 END) AS [30-70 dias],#(lf)    COUNT(CASE WHEN DATEDIFF(day, fechafactura, GETDATE()) > 70 AND DATEDIFF(day, fechafactura, GETDATE()) <= 90 THEN 1 END) AS [70-90 dias],#(lf)    COUNT(CASE WHEN DATEDIFF(day, fechafactura, GETDATE()) > 90 THEN 1 END) AS [Mas de 90 dias],#(lf)    COUNT(*) AS Stock,#(lf)#(tab)AVG(costetotal) as stock_costo_promedio#(lf)FROM YALI_STOCK#(lf)GROUP BY nombrepv, codigo#(lf)"])
